import NaturalLanguage

func analyzeReview(reviewText: String) -> [String: Double] {
    let tagger = NLTagger(tagSchemes: [.sentimentScore])
    tagger.string = reviewText
    let options: NLTagger.Options = [.omitWhitespace, .omitPunctuation, .joinNames]

    var sentimentScore: Double = 0
    var numWords: Int = 0

    tagger.enumerateTags(in: NSRange(location: 0, length: reviewText.utf16.count), unit: .word, scheme: .sentimentScore, options: options) { tag, range in
        if let sentiment = tag?.rawValue, let score = Double(sentiment) {
            sentimentScore += score
            numWords += 1
        }

        return true
    }

